import * as React from 'react';
import { ActionSheet, type ActionSheetAction, Button, Stack } from '@design-schema/rn';

const ACTIONS: ActionSheetAction[] = [
  { id: 'share', label: 'Share', icon: 'external' },
  { id: 'rename', label: 'Rename' },
  { id: 'duplicate', label: 'Duplicate' },
  { id: 'archive', label: 'Archive', disabled: true },
  { id: 'delete', label: 'Delete photo', tone: 'danger' },
];

function Open(): React.JSX.Element {
  const [open, setOpen] = React.useState(true);
  return (
    <Stack gap="loose" align="start">
      <Button label="More actions" onPress={() => setOpen(true)} />
      <ActionSheet heading="Photo.jpg" actions={ACTIONS} open={open} onClose={() => setOpen(false)} onAction={() => setOpen(false)} />
    </Stack>
  );
}

<Open />
